SET NOCOUNT ON;
DECLARE @errors TABLE(Message nvarchar(500));
IF (SELECT COUNT(*) FROM dbo.CampaignFundings WHERE OrderNumber LIKE N'SEED-CF-%' OR Id IN('CF100001-2026-4000-8000-000000000001','CF100002-2026-4000-8000-000000000002','CF100003-2026-4000-8000-000000000003','CF100004-2026-4000-8000-000000000004','CF100005-2026-4000-8000-000000000005','CF100006-2026-4000-8000-000000000006'))<>6 INSERT @errors VALUES(N'Thiếu funding seed.');
IF EXISTS(SELECT 1 FROM dbo.CampaignFundings f WHERE f.Id IN('CF100001-2026-4000-8000-000000000001','CF100002-2026-4000-8000-000000000002','CF100003-2026-4000-8000-000000000003','CF100004-2026-4000-8000-000000000004','CF100005-2026-4000-8000-000000000005','CF100006-2026-4000-8000-000000000006') AND (SELECT ISNULL(SUM(a.Amount),0) FROM dbo.CampaignFundingAllocations a WHERE a.FundingId=f.Id)<>f.CampaignBudgetSnapshot) INSERT @errors VALUES(N'Tổng phân bổ seed không khớp ngân sách.');
IF EXISTS(SELECT 1 FROM @errors) BEGIN SELECT Message VerificationError FROM @errors; THROW 51000,N'Kiểm tra seed campaign funding không đạt.',1; END;
SELECT N'OK' Result,f.Status,COUNT(*) FundingCount,SUM(f.CampaignBudgetSnapshot) Budget FROM dbo.CampaignFundings f WHERE f.Id IN('CF100001-2026-4000-8000-000000000001','CF100002-2026-4000-8000-000000000002','CF100003-2026-4000-8000-000000000003','CF100004-2026-4000-8000-000000000004','CF100005-2026-4000-8000-000000000005','CF100006-2026-4000-8000-000000000006') GROUP BY f.Status ORDER BY f.Status;
